const now = new Date();
function parts(date) { const ps = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin', year:'numeric', month:'2-digit', day:'2-digit' }).formatToParts(date); const o=Object.fromEntries(ps.map(p=>[p.type,p.value])); return `${o.year}-${o.month}-${o.day}`; }
function offset(date) { const p = new Intl.DateTimeFormat('en-US', { timeZone:'Europe/Berlin', timeZoneName:'shortOffset' }).formatToParts(date).find(x=>x.type==='timeZoneName'); const m=String(p?.value||'GMT+1').match(/GMT([+-])(\d{1,2})(?::(\d{2}))?/); return m ? `${m[1]}${m[2].padStart(2,'0')}:${(m[3]||'00').padStart(2,'0')}` : '+01:00'; }
const ymd = parts(now); const off = offset(now);
const filter = `isRead eq false and hasAttachments eq true and receivedDateTime ge ${ymd}T00:00:00${off} and receivedDateTime le ${ymd}T23:59:59${off}`;
return [{ json: { graphUrl: `https://graph.microsoft.com/v1.0/me/mailFolders/Inbox/messages?$top=100&$select=id,subject,from,receivedDateTime,hasAttachments,isRead&$filter=${encodeURIComponent(filter)}&$orderby=receivedDateTime%20desc` } }];

function cleanError(value) {
  if (!value) return 'Unknown error';
  if (typeof value === 'string') return value.slice(0, 600);
  if (value.message) return String(value.message).slice(0, 600);
  return JSON.stringify(value).slice(0, 600);
}
function safeText(value) {
  return String(value ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
function person(mailbox) {
  const e = mailbox?.emailAddress || mailbox || {};
  return { name: e.name || '', email: e.address || '' };
}
function pass(response, extra = {}) {
  return [{ json: { ...extra, response, verificationStatus: 'Passed' } }];
}
function fail(tool, error, action='No Microsoft 365 state was changed.') {
  const msg = cleanError(error);
  return [{ json: { response: `Tool failed: Yes\nTool used: ${tool}\nError message: ${msg}\nAction taken: ${action}\nVerification status: Failed`, toolFailed: true, toolUsed: tool, errorMessage: msg, actionTaken: action, verificationStatus: 'Failed' } }];
}

